package com.jnapanam.sportszone.tournament.model;import com.jnapanam.sportszone.identity.model.User;import jakarta.persistence.*;import java.time.Instant;import java.util.*;
@Entity@Table(name="tournament_teams")public class TournamentTeam{@Id private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="tournament_id")private Tournament tournament;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="captain_user_id")private User captain;@Column(nullable=false,length=120)private String name;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private TeamStatus status;@Column(name="registered_at",nullable=false)private Instant registeredAt;protected TournamentTeam(){}public TournamentTeam(Tournament t,User c,String n){id=UUID.randomUUID();tournament=t;captain=c;name=n.trim();status=TeamStatus.REGISTERED;registeredAt=Instant.now();}public void withdraw(){status=TeamStatus.WITHDRAWN;}public UUID getId(){return id;}public Tournament getTournament(){return tournament;}public User getCaptain(){return captain;}public String getName(){return name;}public TeamStatus getStatus(){return status;}public Instant getRegisteredAt(){return registeredAt;}}
